# Graph traversal: BFS/DFS over an adjacency list with depth limit and path output.
graph = {'a': ['b','c'], 'b': ['d'], 'c': ['d'], 'd': []}
def bfs(start, goal=None, max_depth=5):
    seen, queue = {start}, [(start, [start])]
    order = []
    while queue:
        node, path = queue.pop(0)
        order.append(node)
        if node == goal: return order, path
        if len(path) - 1 >= max_depth: continue
        for nb in graph.get(node, []):
            if nb not in seen: seen.add(nb); queue.append((nb, path + [nb]))
    return order, None
order, path = bfs("a", "d" or None)
print("BFS order:", order)
print("path to goal:", path or "not reached")

